{
  "name": "@johiny/opencode-ntfy-summary",
  "version": "0.1.6",
  "description": "OpenCode plugin that sends push notifications via ntfy.sh with a summary of what the agent just said when the session goes idle.",
  "author": "johiny",
  "license": "MIT",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/johiny/opencode-ntfy.git"
  },
  "homepage": "https://github.com/johiny/opencode-ntfy#readme",
  "bugs": {
    "url": "https://github.com/johiny/opencode-ntfy/issues"
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --target node",
    "prepublishOnly": "/mnt/c/Users/johin/AppData/Roaming/npm/node_modules/bun/bin/bun.exe build src/index.ts --outdir dist --target node\n",
    "typecheck": "tsc --noEmit"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "ntfy",
    "notifications",
    "push-notifications",
    "alerts",
    "summary"
  ],
  "devDependencies": {
    "@opencode-ai/plugin": "^1.0.224",
    "@types/node": "^22.0.0",
    "typescript": "^5.0.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  }
}
